import type { ReactNode } from "react";

type IconProps = {
  className?: string;
};

function Icon({ children, className }: IconProps & { children: ReactNode }) {
  return (
    <svg
      viewBox="0 0 24 24"
      width="24"
      height="24"
      fill="none"
      aria-hidden
      className={className}
    >
      {children}
    </svg>
  );
}

